class Solution {
    long solution(int[] rates, int[] strategy, int k) {
        int n = rates.length;
        long[] preS = new long[n + 1], preR = new long[n + 1];
        for (int i = 0; i < n; i++) {
            preS[i + 1] = preS[i] + (long) strategy[i] * rates[i];
            preR[i + 1] = preR[i] + rates[i];
        }
        long base = preS[n], best = Long.MIN_VALUE;
        int half = k / 2;
        for (int l = 0; l + k <= n; l++) {
            int r = l + k;
            best = Math.max(best, base - (preS[r] - preS[l]) + (preR[r] - preR[l + half]));
        }
        return best;
    }
}

