class Solution {
public:
    long long solution(vector<int>& rates, vector<int>& strategy, int k) {
        int n = rates.size();
        vector<long long> preS(n + 1, 0), preR(n + 1, 0);
        for (int i = 0; i < n; i++) {
            preS[i + 1] = preS[i] + (long long) strategy[i] * rates[i];
            preR[i + 1] = preR[i] + rates[i];
        }
        long long base = preS[n], best = LLONG_MIN;
        int half = k / 2;
        for (int l = 0; l + k <= n; l++) {
            int r = l + k;
            best = max(best, base - (preS[r] - preS[l]) + (preR[r] - preR[l + half]));
        }
        return best;
    }
};
